import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { cp, mkdir, readdir, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { join, relative } from 'node:path';
import { test } from 'node:test';
import { exportFrozenRuntime } from '../../../desktop/scripts/frozen-runtime-export.mjs';
import { bundledBuildFixture } from './helpers/bundled-plugin-build-fixture.js';

async function snapshot(root, directory = root) {
  const entries = [];
  for (const item of await readdir(directory, { withFileTypes: true })) {
    const path = join(directory, item.name);
    const name = relative(root, path).split('\\').join('/');
    assert.ok(!item.isSymbolicLink(), `generated output contains a link: ${name}`);
    const bytes = item.isDirectory() ? null : await readFile(path);
    entries.push([
      name,
      bytes === null ? 'directory' : `${bytes.length}:${createHash('sha256').update(bytes).digest('hex')}`,
    ]);
    if (item.isDirectory()) entries.push(...(await snapshot(root, path)));
  }
  return entries.sort(([a], [b]) => a.localeCompare(b));
}

const bundle = (f) => join(f.pluginRoot, 'bundled-packages');

test('check rejects an extra retired version without mutating any generated bytes', async (t) => {
  const f = await bundledBuildFixture(t, 'Closure fixture');
  assert.equal(f.build().status, 0);
  await cp(join(bundle(f), 'chatgpt-dot/0.1.2'), join(bundle(f), 'chatgpt-dot/0.1.1'), { recursive: true });
  const before = await snapshot(bundle(f));
  const checked = f.build('--check');
  assert.notEqual(checked.status, 0, 'registered current files do not excuse an extra retired release');
  assert.match(checked.stderr, /stale bundled artifact set/);
  assert.deepEqual(await snapshot(bundle(f)), before, '--check must not repair or delete evidence');
});

test('incremental native version migration has the exact fresh file set and frozen-runtime bytes', async (t) => {
  const fresh = await bundledBuildFixture(t, 'Closure fixture');
  const incremental = await bundledBuildFixture(t, 'Closure fixture');
  const currentProducer = await readFile(incremental.producerPath, 'utf8');
  assert.match(currentProducer, /version: '0\.1\.2'/);
  await cp(incremental.assets, join(incremental.assets, '../../0.1.1/assets'), { recursive: true });
  await writeFile(incremental.producerPath, currentProducer.replace("version: '0.1.2'", "version: '0.1.1'"));
  let result = incremental.build();
  assert.equal(result.status, 0, result.stderr);
  assert.ok((await readdir(join(bundle(incremental), 'chatgpt-dot'))).includes('0.1.1'));
  await writeFile(incremental.producerPath, currentProducer);
  await mkdir(join(bundle(incremental), 'retired-catalog/empty'), { recursive: true });
  await writeFile(join(bundle(incremental), 'abandoned.tmp'), 'unregistered output');
  await writeFile(join(incremental.pluginRoot, 'unrelated.js'), 'not owned by this producer');
  result = incremental.build();
  assert.equal(result.status, 0, result.stderr);
  result = fresh.build();
  assert.equal(result.status, 0, result.stderr);
  const expected = await snapshot(bundle(fresh));
  assert.deepEqual(await snapshot(bundle(incremental)), expected);
  assert.deepEqual(await readdir(join(bundle(incremental), 'chatgpt-dot')), ['0.1.2']);
  assert.equal(await readFile(join(incremental.pluginRoot, 'unrelated.js'), 'utf8'), 'not owned by this producer');
  assert.equal(incremental.build('--check').status, 0);

  // Exercise the actual recursive release exporter, with only its unrelated
  // dependency inputs reduced to a self-owned empty workspace.
  for (const sharedDependencies of [false, true]) {
    const exported = [];
    for (const f of [fresh, incremental]) {
      const workspace = join(f.root, `workspace-${sharedDependencies}`);
      await mkdir(join(workspace, 'packages/api/dist/domains/plugin'), { recursive: true });
      await mkdir(join(workspace, 'node_modules'));
      await writeFile(join(workspace, 'packages/api/package.json'), '{"name":"@cat-cafe/api"}');
      const lock = join(workspace, 'pnpm-lock.yaml');
      await writeFile(lock, 'frozen closure fixture');
      await cp(bundle(f), join(workspace, 'packages/api/dist/domains/plugin/bundled-packages'), { recursive: true });
      const destination = join(f.root, `frozen-${sharedDependencies}`);
      exportFrozenRuntime(workspace, destination, ['api'], lock, { sharedDependencies });
      exported.push(await snapshot(join(destination, 'api/dist/domains/plugin/bundled-packages')));
    }
    assert.deepEqual(exported[0], expected);
    assert.deepEqual(exported[1], expected);
  }
});

test('bounded namespace replacement removes an output link without following it or touching siblings', async (t) => {
  const f = await bundledBuildFixture(t, 'Closure fixture');
  assert.equal(f.build().status, 0);
  const external = join(f.root, 'outside-output');
  await mkdir(external);
  await writeFile(join(external, 'keep.txt'), 'outside namespace');
  await rm(bundle(f), { recursive: true });
  await symlink(external, bundle(f), process.platform === 'win32' ? 'junction' : 'dir');
  const built = f.build();
  assert.equal(built.status, 0, built.stderr);
  assert.deepEqual(await readdir(external), ['keep.txt']);
  assert.equal(await readFile(join(external, 'keep.txt'), 'utf8'), 'outside namespace');
  await snapshot(bundle(f));
  assert.equal(f.build('--check').status, 0);
});
